RNC_st.name='RNC'; 
RNC_st.lat=30.32;
RNC_st.lon=78.41;
RNC_st.alt=1950;
RNC_st.env='Mt';
RNC_st.footp='RB';
%%
% data imported via the import tool from matlab
 RNC_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\RNC_2016-2026_Hour.csv", [2, Inf]);
RNC_rd_h.Properties.DimensionNames{1}='Time';
RNC_rd_h.Properties.VariableNames{2}='Ba1_A';
RNC_rd_h.Properties.VariableNames{3}='Ba2_A';
RNC_rd_h.Properties.VariableNames{4}='Ba3_A';
RNC_rd_h.Properties.VariableNames{5}='Ba4_A';
RNC_rd_h.Properties.VariableNames{6}='Ba5_A';
RNC_rd_h.Properties.VariableNames{7}='Ba6_A';
RNC_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(RNC_rd_h);
%%
RNC_rd=retime(RNC_rd_h,'daily',@nanmedian);
%%
% new data in October:
rnc_hourly.Properties.DimensionNames{1}='Time';
rnc_hourly.Properties.VariableNames{2}='Ba1_A';
rnc_hourly.Properties.VariableNames{3}='Ba2_A';
rnc_hourly.Properties.VariableNames{4}='Ba3_A';
rnc_hourly.Properties.VariableNames{5}='Ba4_A';
rnc_hourly.Properties.VariableNames{6}='Ba5_A';
rnc_hourly.Properties.VariableNames{7}='Ba6_A';
rnc_hourly.Properties.VariableNames{8}='Ba7_A';
names_rd2=fieldnames(rnc_hourly);
RNC_rd2=retime(rnc_hourly,'daily',@nanmedian);
%%
RNC_rd=[RNC_rd;RNC_rd2];
%%
datevec(RNC_rd.Time(1)) % begin in 2019 June,  %[output:7a3f5d0a]
datevec(RNC_rd.Time(end)) % end in 2024 august too short %[output:0c280ed0]
plotFigControl(RNC_rd,RNC_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
RNC_cal=compute_exp_D(RNC_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:600ff552] %[output:829f7b86] %[output:38f4151c] %[output:422ec642] %[output:2a9c43ab] %[output:93258bf7] %[output:5571aaf8] %[output:6f833b3e] %[output:91101f0b] %[output:8550f051] %[output:6157d6ee] %[output:14983c2f] %[output:16e43592] %[output:278421d9] %[output:5eb946f4] %[output:7c7d5c10]
plotFigControl_cal(RNC_cal,RNC_st.name); %[output:61434ad4] %[output:6f638cfb] %[output:4ce4a6af]
%%
% make abs
sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19]; %for the 7 wavelengths with an exponent of -1
RNC_rd.Ba1_A=RNC_rd.Ba1_A .*sigma(1);
RNC_rd.Ba2_A=RNC_rd.Ba2_A .*sigma(2);
RNC_rd.Ba3_A=RNC_rd.Ba3_A .*sigma(3);
RNC_rd.Ba4_A=RNC_rd.Ba4_A .*sigma(4);
RNC_rd.Ba5_A=RNC_rd.Ba5_A .*sigma(5);
RNC_rd.Ba6_A=RNC_rd.Ba6_A .*sigma(6);
RNC_rd.Ba7_A=RNC_rd.Ba7_A .*sigma(7);
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
RNC_cal=compute_exp_D(RNC_rd,names_abs,lambdaAE7); %[output:042d3a2e] %[output:6783fcf1] %[output:8f92b08a] %[output:4d93a1f9] %[output:444a1efe] %[output:91109ab4] %[output:2680d346] %[output:58f01c35] %[output:7c9b2733]
plotFigControl_cal(RNC_cal,RNC_st.name); %[output:8c59a0b5] %[output:6f0d2e7b] %[output:72d2ffbe]
%%
%HOMOGENEITY

break_RNCabs_BP=change_point_analysis_Def(RNC_rd,names_abs,0.05,'RNC','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:73b52d7b]
T_RNCabs_BP=make_table_breakpoints_def(break_RNCabs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:350f5da0]
break_RNCexpA_BP=change_point_analysis_Def(RNC_cal,names_expA,0.05,'RNC','Absorption exponent'); %[output:0679a779] %[output:5296e524] %[output:4b2350bc] %[output:6ac57efd]
T_RNCexpA_BP=make_table_breakpoints_def(break_RNCexpA_BP);
%%
RNC_tr=outerjoin(RNC_rd, RNC_cal);
RNC_tr.y=year(RNC_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2016-01-01','2026-01-01');
RNC_tr=RNC_tr(P,:);

% % names=fieldnames(RNC_tr);
% % c=startsWith(names,["U"]) | endsWith(names,["_dry","_A","_br","_gr"]) | contains(names,["00","3","tsi"]);
% % N=names(c);
% % for i=1:length(N)
% %     RNC_tr.(N{i})=[];
% % end

%
RNC_tr.Ba1_A=[];
RNC_tr.Ba2_A=[];
RNC_tr.Ba4_A=[];
RNC_tr.Ba5_A=[];
RNC_tr.Ba6_A=[];
RNC_tr.Ba7_A=[];

RNC_tr.BB=[];

RNC_tr.expA_bgAE=[];
RNC_tr.expA_brAE=[];
RNC_tr.expA_grAE=[];
%%
% % % data in Mm-1
% % RNC_tr.Ba3_A=RNC_tr.Ba3_A.*1e6;
%%
[RNCresult_MK,RNCresult_LMSlog,RNCresult_LMSlin]=all_trend_STN(RNC_tr,RNC_st); %[output:67c4d353] %[output:2e8249f9] %[output:5b031a7b] %[output:90ce773e] %[output:395c7890] %[output:49c0dce9] %[output:328ec7d9]

writetable(RNCresult_MK,'RNC_res_MK_present_10y.txt'); %, 'delimiter',',' )
writetable(RNCresult_LMSlog,'RNC_res_LMSlog.txt'); 
writetable(RNCresult_LMSlin,'RNC_res_LMSlin.txt'); 
plot_10y_in_two(RNCresult_MK, RNC_st,'y');
%%
 timetable_to_netcdf(RNC_tr,'RNC_tr_def.nc'); %[output:894c1c65] %[output:4088463e]

